const tracks={
 paris:{name:'塞納河慢鋼琴',step:2.8,notes:[60,64,67,null,64,71,67,null,57,60,64,null,60,67,64,null,53,57,60,null,57,64,60,null,55,59,62,null,59,67,62,null],harmonics:[0,1,.2,.075,.025,.008],decay:4.2},
 taipei:{name:'河岸木質輕音',step:3.2,notes:[62,null,69,66,64,null,69,null,59,null,66,62,64,null,66,null,55,null,62,59,57,null,62,null,57,null,64,62,59,null,64,null],harmonics:[0,1,.1,.03,.05,.012],decay:3.8}
};

// Original, locally synthesized motifs. One city session is connected at a time.
export class AmbientPlayer{
 constructor(onState=()=>{}){this.onState=onState;this.volume=.25;this.playing=false;this.city='paris';this.token=0;this.session=null;this.timer=null;this.stopping=null;}
 async ensureAudio(){if(!this.context){const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)throw new Error('此瀏覽器無法播放音樂');this.context=new Audio({latencyHint:'playback'});this.master=this.context.createGain();this.master.gain.value=this.volume;const limiter=this.context.createDynamicsCompressor();limiter.threshold.value=-18;limiter.ratio.value=4;limiter.knee.value=15;this.master.connect(limiter);limiter.connect(this.context.destination);}await this.context.resume();if(this.context.state!=='running')throw new Error('請再次按播放以啟用聲音');}
 setVolume(value){this.volume=Math.max(0,Math.min(1,value));if(this.context)this.master.gain.setTargetAtTime(this.volume,this.context.currentTime,.12);}
 createSession(city){const ctx=this.context,bus=ctx.createGain(),dry=ctx.createGain(),wet=ctx.createGain(),reverb=ctx.createConvolver();bus.gain.value=0;dry.gain.value=.84;wet.gain.value=.16;const duration=2.7,impulse=ctx.createBuffer(2,Math.floor(ctx.sampleRate*duration),ctx.sampleRate);for(let c=0;c<2;c++){const samples=impulse.getChannelData(c);for(let i=0;i<samples.length;i++)samples[i]=(Math.random()*2-1)*Math.pow(1-i/samples.length,3.5)*.4;}reverb.buffer=impulse;bus.connect(dry);dry.connect(this.master);bus.connect(reverb);reverb.connect(wet);wet.connect(this.master);const track=tracks[city],real=new Float32Array(track.harmonics.length),imag=new Float32Array(track.harmonics),wave=ctx.createPeriodicWave(real,imag);bus.gain.linearRampToValueAtTime(1,ctx.currentTime+1.2);return{city,bus,dry,wet,reverb,wave,voices:new Set(),index:0,next:ctx.currentTime+.15};}
 note(session,midi,time){const ctx=this.context,track=tracks[session.city],osc=ctx.createOscillator(),gain=ctx.createGain(),filter=ctx.createBiquadFilter();osc.setPeriodicWave(session.wave);osc.frequency.value=440*2**((midi-69)/12);filter.type='lowpass';filter.frequency.value=session.city==='paris'?1400:1100;filter.Q.value=.35;gain.gain.setValueAtTime(.0001,time);gain.gain.exponentialRampToValueAtTime(.10,time+.06);gain.gain.exponentialRampToValueAtTime(.0001,time+track.decay);osc.connect(filter);filter.connect(gain);gain.connect(session.bus);session.voices.add(osc);osc.onended=()=>{session.voices.delete(osc);osc.disconnect();filter.disconnect();gain.disconnect();};osc.start(time);osc.stop(time+track.decay+.08);}
 schedule(){const s=this.session;if(!this.playing||!s)return;const ctx=this.context,track=tracks[s.city];if(s.next<ctx.currentTime-.5)s.next=ctx.currentTime+.1;while(s.next<ctx.currentTime+2){const note=track.notes[s.index%track.notes.length];if(note!==null)this.note(s,note,s.next);if(s.index%8===0&&note!==null)this.note(s,note-12,s.next+.03);s.index++;s.next+=track.step;}}
 async stopSession(){clearInterval(this.timer);this.timer=null;const session=this.session;this.session=null;if(!session){if(this.stopping)await this.stopping;return;}const now=this.context.currentTime;session.bus.gain.cancelScheduledValues(now);session.bus.gain.setTargetAtTime(0,now,.14);this.stopping=new Promise(resolve=>setTimeout(resolve,650));await this.stopping;for(const osc of session.voices)try{osc.stop();}catch{}session.bus.disconnect();session.dry.disconnect();session.wet.disconnect();session.reverb.disconnect();this.stopping=null;}
 async play(city){const request=++this.token;this.playing=false;await this.ensureAudio();if(request!==this.token)return;await this.stopSession();if(request!==this.token)return;this.city=city;this.session=this.createSession(city);this.playing=true;this.schedule();this.timer=setInterval(()=>this.schedule(),200);this.onState(true,city);}
 async pause(){++this.token;this.playing=false;this.onState(false,this.city);await this.stopSession();}
}

export function installMusic(){const bar=document.createElement('section');bar.className='music-bar';bar.setAttribute('aria-label','兩地輕音樂');bar.innerHTML='<span class="music-icon" aria-hidden="true">♫</span><div class="music-copy"><span class="music-title">留一點音樂給此刻</span><small id="music-status" aria-live="polite">原創輕音樂 · 未播放</small></div><div class="music-cities" role="group" aria-label="選擇播放城市"><button data-music-city="paris" class="active" aria-pressed="true">巴黎</button><button data-music-city="taipei" aria-pressed="false">台北</button></div><button id="music-play" aria-label="播放背景音樂" aria-pressed="false">▷ 播放</button><label class="music-volume" for="music-volume">音量<input id="music-volume" type="range" min="0" max="60" value="25" aria-label="背景音樂音量"></label>';
 document.querySelector('footer').before(bar);let selected='paris',intent=false,request=0;const play=bar.querySelector('#music-play'),status=bar.querySelector('#music-status');const update=(playing,city)=>{play.textContent=playing?'Ⅱ 暫停':'▷ 播放';play.setAttribute('aria-pressed',String(playing));play.setAttribute('aria-label',playing?'暫停背景音樂':'播放背景音樂');status.textContent=playing?tracks[city].name+' · 播放中':'原創輕音樂 · 未播放';};const player=new AmbientPlayer(update);
 const start=async()=>{const current=++request;status.textContent='準備音樂…';try{await player.play(selected);if(current!==request&&!intent)await player.pause();}catch(error){if(current===request){intent=false;update(false,selected);status.textContent=error.message||'音樂未能播放，請再試一次';}}};
 bar.querySelectorAll('[data-music-city]').forEach(button=>button.addEventListener('click',()=>{if(selected===button.dataset.musicCity)return;selected=button.dataset.musicCity;bar.querySelectorAll('[data-music-city]').forEach(b=>{const active=b===button;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});if(intent)start();else status.textContent=tracks[selected].name+' · 未播放';}));
 play.addEventListener('click',()=>{intent=!intent;if(intent)start();else{request++;player.pause();}});bar.querySelector('#music-volume').addEventListener('input',e=>player.setVolume(Number(e.target.value)/100));window.addEventListener('pagehide',()=>player.pause());return player;
}

